"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { type ComponentType, useId, useMemo, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { CashFlowChart } from "./01-finance/cash-flow-chart";
import { ACCOUNTS, type AccountId, MAX_DATE, MIN_DATE, type Movement } from "./01-finance/data";
import { FinancePeriodPicker } from "./01-finance/date-range-picker";
import { ArrowDownLeftIcon, ArrowUpRightIcon, DownloadIcon, WalletIcon } from "./01-finance/icons";
import { allowanceUsed, computeView, type DateRange, money0 } from "./01-finance/model";
import { MotionButton } from "./01-finance/motion-button";
import { MovementsTable } from "./01-finance/movements-table";
import { NumberTicker } from "./01-finance/number-ticker";
import { CardDetailsDialog, LatestMovements, MonthlyAllowance, MovementDialog, SpendingAccount } from "./01-finance/side-panels";
const PREVIEW_FLUSH_CSS = "body>main:has(>main.\\@container\\/planning){padding-top:0;padding-bottom:0;--preview-viewport-height:100svh}";
const LEGEND_BUTTON = "art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:inline-flex art:h-9 art:items-center art:gap-2 art:px-1 art:text-xs art:text-muted-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring";
function KpiCard({ icon: Icon, label, value, caption, }: {
    icon: ComponentType<{
        className?: string;
    }>;
    label: string;
    value: string;
    caption: string;
}) {
    return (<div className="art:flex art:min-w-0 art:flex-col art:rounded-3xl art:border art:border-border art:p-1.5 art:bg-background">
      <dt className="art:flex art:items-center art:gap-3 art:px-4 art:py-3 art:text-muted-foreground">
        <span aria-hidden="true" className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border art:[&>svg]:size-4">
          <Icon />
        </span>
        <span className="art:font-mono art:font-medium art:uppercase art:tracking-tight art:text-xs">{label}</span>
      </dt>
      <dd className="art:flex art:flex-1 art:flex-col art:justify-between art:gap-4 art:rounded-2xl art:bg-background art:p-4 art:border art:border-border">
        <div className="art:flex art:min-h-9 art:items-center">
          <div className="art:flex art:min-w-0 art:flex-wrap art:items-center art:gap-x-2 art:gap-y-1">
            <NumberTicker text={value} className="art:whitespace-nowrap art:text-2xl art:font-medium art:tabular-nums art:tracking-tight art:text-foreground art:@5xl:text-3xl"/>
          </div>
        </div>
        <p className="art:text-xs art:text-muted-foreground">{caption}</p>
      </dd>
    </div>);
}
export default function DashboardsFinance() {
    const titleId = useId();
    const reduce = useReducedMotion();
    const [accountId, setAccountId] = useState<AccountId>("studio");
    const [range, setRange] = useState<DateRange>({ start: MIN_DATE, end: MAX_DATE });
    const [showIn, setShowIn] = useState(true);
    const [showOut, setShowOut] = useState(true);
    const [balanceHidden, setBalanceHidden] = useState(false);
    const [paused, setPaused] = useState<Record<AccountId, boolean>>({ studio: false, project: false });
    const [detailsOpen, setDetailsOpen] = useState(false);
    const [viewing, setViewing] = useState<Movement | null>(null);
    const [viewOpen, setViewOpen] = useState(false);
    const [announcement, setAnnouncement] = useState("");
    const account = ACCOUNTS.find((a) => a.id === accountId) ?? ACCOUNTS[0];
    const view = useMemo(() => computeView(accountId, range), [accountId, range]);
    const used = useMemo(() => allowanceUsed(accountId), [accountId]);
    if (!account)
        return null;
    return (<main aria-labelledby={titleId} className="art:@container/planning art:min-h-screen art:w-full art:bg-muted/20 art:text-foreground">

      <style href="finance-dashboard-flush-preview" precedence="default">
        {PREVIEW_FLUSH_CSS}
      </style>
      <div className="art:mx-auto art:max-w-screen-2xl art:space-y-5 art:px-4 art:py-6 art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-8 art:@min-[1024px]/artemis:px-8">
        <motion.header className="art:flex art:flex-col art:justify-between art:gap-5 art:@5xl/planning:flex-row art:@5xl/planning:items-end" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
          <div>
            <p className="art:mb-3 art:text-xs art:text-muted-foreground">
              Workspace <span className="art:px-2 art:text-border">/</span>Accounts &amp; cash flow
            </p>
            <h1 id={titleId} className="art:text-2xl art:font-normal art:tracking-tight art:@min-[640px]/artemis:text-3xl">
              <span className="art:text-muted-foreground">{"Your finances"},</span> {"Cameron"}
            </h1>
            <p className="art:mt-3 art:text-sm art:text-muted-foreground">Follow your cash flow, spending, and account movements in one place.</p>
          </div>
          <div className="art:flex art:flex-wrap art:items-center art:gap-2">
            <FinancePeriodPicker range={range} onChange={setRange}/>
            <MotionButton className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" disabled={view.movements.length === 0} onClick={() => setAnnouncement(`${view.movements.length} movements exported.`)}>
              <DownloadIcon className="art:size-4"/>
              Export
            </MotionButton>
          </div>
        </motion.header>
        <div className="art:grid art:items-start art:gap-5 art:@5xl/planning:grid-cols-[minmax(0,2.25fr)_minmax(320px,1fr)]">
          <div className="art:min-w-0 art:space-y-5">
            <section aria-label="Key performance indicators" className="art:@container art:w-full art:min-w-0 art:[&>dl>div]:bg-muted art:@lg:[&>dl]:grid-cols-3">
              <dl className="art:grid art:grid-cols-1 art:gap-3 art:@lg:grid-cols-2 art:@5xl:grid-cols-4">
                <KpiCard icon={ArrowDownLeftIcon} label="Money in" value={money0(view.moneyIn)} caption="Settled incoming payments"/>
                <KpiCard icon={ArrowUpRightIcon} label="Money out" value={money0(view.moneyOut)} caption="Settled account spending"/>
                <KpiCard icon={WalletIcon} label="Net flow" value={money0(view.net)} caption="Incoming less outgoing"/>
              </dl>
            </section>
            <section aria-label="Cash flow" className="art:min-w-0 art:rounded-2xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
              <div className="art:flex art:flex-wrap art:items-start art:justify-between art:gap-4">
                <div>
                  <h2 className="art:text-xl art:font-medium">Cash flow</h2>
                  <p className="art:mt-1 art:text-xs art:text-muted-foreground">Settled movements across the selected period</p>
                </div>
                <div className="art:flex art:gap-3">
                  <MotionButton className={`${LEGEND_BUTTON}${showIn ? "" : " art:opacity-40"} art:rounded-full`} aria-pressed={showIn} onClick={() => {
            if (showIn && !showOut)
                return;
            setShowIn(!showIn);
        }}>
                    <span className="art:size-2 art:rounded-full art:bg-primary"/>
                    Money in
                  </MotionButton>
                  <MotionButton className={`${LEGEND_BUTTON}${showOut ? "" : " art:opacity-40"} art:rounded-full`} aria-pressed={showOut} onClick={() => {
            if (showOut && !showIn)
                return;
            setShowOut(!showOut);
        }}>
                    <span className="art:size-2 art:rounded-full art:bg-muted-foreground/35"/>
                    Money out
                  </MotionButton>
                </div>
              </div>
              <div className="art:mt-4 art:flex art:flex-wrap art:items-baseline art:gap-3">
                <NumberTicker text={money0(view.net)} className="art:text-3xl art:font-medium art:tabular-nums art:tracking-tight"/>
                <span className="art:text-xs art:text-muted-foreground">Net movement</span>
              </div>
              <CashFlowChart months={view.months} showIn={showIn} showOut={showOut}/>
            </section>
            <MovementsTable movements={view.movements} onView={(movement) => {
            setViewing(movement);
            setViewOpen(true);
        }} onAnnounce={setAnnouncement}/>
          </div>
          <aside className="art:min-w-0 art:space-y-5">
            <SpendingAccount account={account} onAccountChange={setAccountId} hidden={balanceHidden} onToggleHidden={() => setBalanceHidden((h) => !h)} paused={paused[accountId]} onTogglePaused={() => setPaused((p) => ({ ...p, [accountId]: !p[accountId] }))} onShowDetails={() => setDetailsOpen(true)}/>
            <MonthlyAllowance used={used} limit={account.allowance}/>
            <LatestMovements movements={view.movements}/>
          </aside>
        </div>
        <output className="art:sr-only" aria-live="polite">
          {announcement}
        </output>
        <footer className="art:text-xs art:text-muted-foreground">
          Demo workspace · Snapshot {"Sep 30"}, {"2026"}
        </footer>
      </div>
      <CardDetailsDialog open={detailsOpen} account={account} paused={paused[accountId]} onClose={() => setDetailsOpen(false)}/>
      <MovementDialog open={viewOpen} movement={viewing} onClose={() => setViewOpen(false)}/>
    </main>);
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { type MonthRow, money0, moneyCompact } from "./model";
interface TooltipEntry {
    name?: string | number;
    value?: number | string | ReadonlyArray<number | string>;
    payload?: MonthRow;
}
function CashFlowTooltip({ active, payload }: {
    active?: boolean;
    payload?: ReadonlyArray<TooltipEntry>;
}) {
    if (!active || !payload || payload.length === 0)
        return null;
    const row = payload[0]?.payload;
    if (!row)
        return null;
    return (<div className="art:rounded-xl art:border art:border-border art:bg-background art:p-3 art:text-xs">
      <p className="art:mb-2 art:text-muted-foreground">{row.title}</p>
      {payload.map((entry) => (<p key={String(entry.name)} className="art:mt-1 art:flex art:justify-between art:gap-6">
          <span>{entry.name}</span>
          <span className="art:font-medium art:tabular-nums">{money0(Number(entry.value ?? 0))}</span>
        </p>))}
    </div>);
}
export function CashFlowChart({ months, showIn, showOut }: {
    months: MonthRow[];
    showIn: boolean;
    showOut: boolean;
}) {
    const reduce = useReducedMotion();
    return (<>
      <motion.figure aria-label="Monthly incoming and outgoing funds" className="art:mt-6 art:h-64 art:min-w-0 art:@min-[640px]/artemis:h-72" initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.4, ease: ARTEMIS_EASE_OUT }}>
        <ResponsiveContainer width="100%" height="100%" minWidth={0}>
          <BarChart data={months} margin={{ top: 4, right: 0, bottom: 0, left: 0 }} barCategoryGap="22%">
            <CartesianGrid vertical={false} stroke="var(--artemis-border)" strokeDasharray="3 5"/>
            <XAxis dataKey="label" axisLine={false} tickLine={false} tickMargin={12} minTickGap={16} tick={{ fill: "var(--artemis-muted-foreground)", className: "art:text-xs" }}/>
            <YAxis width={48} tickCount={4} axisLine={false} tickLine={false} tickFormatter={(value: number) => moneyCompact(value)} tick={{ fill: "var(--artemis-muted-foreground)", className: "art:text-xs" }}/>
            <Tooltip cursor={{ fill: "var(--artemis-muted)", fillOpacity: 0.4 }} content={<CashFlowTooltip />}/>

            {showIn ? (<Bar dataKey="moneyIn" name="Money in" fill="var(--artemis-primary)" radius={[4, 4, 0, 0]} maxBarSize={24} isAnimationActive={false}/>) : null}
            {showOut ? (<Bar dataKey="moneyOut" name="Money out" fill="var(--artemis-muted-foreground)" fillOpacity={0.25} radius={[4, 4, 0, 0]} maxBarSize={24} isAnimationActive={false}/>) : null}
          </BarChart>
        </ResponsiveContainer>
      </motion.figure>
      <table className="art:sr-only">
        <caption>Monthly cash flow in {"USD"}</caption>
        <thead>
          <tr>
            <th scope="col">Month</th>
            <th scope="col">Money in</th>
            <th scope="col">Money out</th>
          </tr>
        </thead>
        <tbody>
          {months.map((row) => (<tr key={row.key}>
              <th scope="row">{row.key}</th>
              <td>{money0(row.moneyIn)}</td>
              <td>{money0(row.moneyOut)}</td>
            </tr>))}
        </tbody>
      </table>
    </>);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion } from "motion/react";
import { useId } from "react";
import { artemisCx } from "../../../../lib/utils";
export type CheckState = "checked" | "unchecked" | "indeterminate";
export function TableCheckbox({ state, label, onToggle, stableId, }: {
    state: CheckState;
    label: string;
    onToggle: () => void;
    stableId?: string;
