        <AnimatePresence initial={false}>
          {on ? (<motion.svg key={state} width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} transition={{ duration: 0.15 }}>
              <title>{state === "indeterminate" ? "Partially selected" : "Selected"}</title>
              <motion.path d={state === "indeterminate" ? "M6 12h12" : "M5 13l4 4L19 7"} pathLength="1" strokeDasharray="1 1" initial={{ strokeDashoffset: 1 }} animate={{ strokeDashoffset: 0 }} transition={{ duration: 0.22 }}/>
            </motion.svg>) : null}
        </AnimatePresence>
