}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent as ReactKeyboardEvent, useCallback, useEffect, useId, useLayoutEffect, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
import { MAX_DATE, MIN_DATE } from "./data";
import { CalendarDaysIcon, ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from "./icons";
import { addDays, addMonths, ariaDate, type DateRange, type Day, dayNumber, daysInMonth, formatPeriod, longDate, MONTHS_LONG, parseIso, toIso, weekday, } from "./model";
import { MotionButton } from "./motion-button";
const MIN = parseIso(MIN_DATE);
const MAX = parseIso(MAX_DATE);
const MIN_N = dayNumber(MIN);
const MAX_N = dayNumber(MAX);
const WEEKDAYS = [
    ["Sun", "Sunday"],
    ["Mon", "Monday"],
    ["Tue", "Tuesday"],
    ["Wed", "Wednesday"],
    ["Thu", "Thursday"],
    ["Fri", "Friday"],
    ["Sat", "Saturday"],
] as const;
type PresetId = "This month" | "Year to date" | "All activity";
const PRESETS: ReadonlyArray<{
    id: PresetId;
    range: DateRange;
}> = [
    { id: "This month", range: { start: "2026-09-01", end: MAX_DATE } },
    { id: "Year to date", range: { start: "2026-01-01", end: MAX_DATE } },
    { id: "All activity", range: { start: MIN_DATE, end: MAX_DATE } },
];
type View = "days" | "months" | "years";
interface Draft {
    start: Day;
    end: Day | null;
}
const monthIndex = (day: Pick<Day, "y" | "m">) => day.y * 12 + day.m - 1;
const clampDay = (day: Day): Day => {
    const n = dayNumber(day);
    if (n < MIN_N)
        return MIN;
    if (n > MAX_N)
        return MAX;
    return day;
};
const firstEnabledInMonth = (y: number, m: number): Day => clampDay({ y, m, d: 1 });
const VIEW_VARIANTS = {
    enter: (dir: number) => ({ opacity: 0, x: dir * 12 }),
    center: { opacity: 1, x: 0, transition: { duration: 0.18, ease: ARTEMIS_EASE_OUT } },
    exit: (dir: number) => ({ opacity: 0, x: dir * -8, transition: { duration: 0.12, ease: ARTEMIS_EASE_OUT } }),
};
const HEADER_MONTH_BASE = "art:items-center art:gap-1.5 art:rounded-full art:px-2 art:py-1.5 art:text-sm art:font-semibold art:transition-colors art:hover:bg-muted art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-40";
const HEADER_YEAR = "art:inline-flex art:items-center art:gap-1.5 art:rounded-full art:px-2 art:py-1.5 art:text-sm art:font-medium art:tabular-nums art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-40";
const NAV_BASE = "art:size-8 art:shrink-0 art:items-center art:justify-center art:rounded-full art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:pointer-events-none art:disabled:opacity-30";
const DAY_BUTTON = "art:relative art:mx-auto art:flex art:h-8 art:w-full art:max-w-8 art:items-center art:justify-center art:rounded-full art:text-xs art:tabular-nums art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:disabled:opacity-30";
const CHOICE_BUTTON = "art:flex art:h-13 art:items-center art:justify-center art:rounded-xl art:px-1 art:text-sm art:tabular-nums art:transition-colors art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:disabled:opacity-25";
const PRESET_BUTTON = "art:rounded-full art:px-3 art:py-1.5 art:text-xs art:font-medium art:transition-colors art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-40";
const KEYBOARD_HELP = "Use arrow keys to navigate dates, Home and End for the week, Page Up and Page Down for months, Shift with Page Up or Page Down for years. Enter or Space selects a date. Use the month and year buttons to jump directly. In the month or year choices, use arrow keys to move and Escape to return.";
function Calendar({ initial, label, onCancel, onApply, }: {
    initial: DateRange;
    label: string;
    onCancel: () => void;
    onApply: (range: DateRange) => void;
}) {
    const baseId = useId();
    const gridId = `${baseId}H2_`;
    const helpId = `${baseId}H1_`;
    const [draft, setDraft] = useState<Draft>(() => ({ start: parseIso(initial.start), end: parseIso(initial.end) }));
    const [viewMonth, setViewMonth] = useState<{
        y: number;
        m: number;
    }>(() => {
        const end = parseIso(initial.end);
        return { y: end.y, m: end.m };
    });
    const [focusDay, setFocusDay] = useState<Day>(() => {
        const start = parseIso(initial.start);
        const end = parseIso(initial.end);
        return start.y === end.y && start.m === end.m ? start : firstEnabledInMonth(end.y, end.m);
    });
    const [view, setView] = useState<View>("days");
    const [dir, setDir] = useState(1);
    const [hover, setHover] = useState<Day | null>(null);
    const [message, setMessage] = useState("");
    const [choiceFocus, setChoiceFocus] = useState<{
        key: string;
        value: number;
    } | null>(null);
    const focusRef = useRef<HTMLButtonElement | null>(null);
    const focusTarget = useRef<"day" | "month" | "year" | "choice" | null>("day");
    const monthButtonRef = useRef<HTMLButtonElement>(null);
    const yearButtonRef = useRef<HTMLButtonElement>(null);
    const choiceRef = useRef<HTMLButtonElement | null>(null);
    useLayoutEffect(() => {
        const target = focusTarget.current;
        focusTarget.current = null;
        if (target === "day")
            focusRef.current?.focus({ preventScroll: true });
        else if (target === "month")
            monthButtonRef.current?.focus({ preventScroll: true });
        else if (target === "year")
            yearButtonRef.current?.focus({ preventScroll: true });
        else if (target === "choice")
            choiceRef.current?.focus({ preventScroll: true });
    });
    const goToMonth = (y: number, m: number) => {
        const next = monthIndex({ y, m });
        const current = monthIndex(viewMonth);
        if (next === current)
            return;
        setDir(next > current ? 1 : -1);
        setViewMonth({ y, m });
    };
    const startN = dayNumber(draft.start);
    const endN = draft.end ? dayNumber(draft.end) : null;
    const previewN = endN === null && hover ? dayNumber(hover) : null;
    const bandLo = endN !== null ? startN : previewN !== null ? Math.min(startN, previewN) : startN;
    const bandHi = endN !== null ? endN : previewN !== null ? Math.max(startN, previewN) : startN;
    const selectDay = (day: Day) => {
        const n = dayNumber(day);
        if (draft.end === null) {
            const lo = n < startN ? day : draft.start;
            const hi = n < startN ? draft.start : day;
            setDraft({ start: lo, end: hi });
            setMessage(`${longDate(toIso(lo))} to ${longDate(toIso(hi))} selected.`);
        }
        else {
            setDraft({ start: day, end: null });
            setMessage(`Start date ${ariaDate(day)}. Choose an end date.`);
        }
        setHover(null);
        setFocusDay(day);
    };
    const applyPreset = (id: PresetId, range: DateRange) => {
        const start = parseIso(range.start);
        setDraft({ start, end: parseIso(range.end) });
        setFocusDay(start);
        setView("days");
        goToMonth(start.y, start.m);
        setMessage(`${id} selected.`);
    };
    const moveFocus = (next: Day) => {
        const day = clampDay(next);
        if (dayNumber(day) !== dayNumber(next))
            return;
        setFocusDay(day);
        goToMonth(day.y, day.m);
        focusTarget.current = "day";
